package cache

import (
	"container/list"
	"sync"
)

// entry holds a cache key and its associated value.
type entry struct {
	key   string
	value int
}

// LRU is a fixed-capacity least-recently-used cache.
type LRU struct {
	capacity int
	mu       sync.Mutex
	items    map[string]*list.Element
	order    *list.List // front = most recently used, back = least recently used
}

// NewLRU creates a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity: capacity,
		items:    make(map[string]*list.Element),
		order:    list.New(),
	}
}

// Get retrieves a value by key, marking it as most recently used.
// The second return value reports whether the key was found.
func (c *LRU) Get(key string) (int, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	el, ok := c.items[key]
	if !ok {
		return 0, false
	}

	c.order.MoveToFront(el)
	return el.Value.(*entry).value, true
}

// Put stores a value under key. Updating an existing key does not grow the
// cache. When the cache is full, the least recently used entry is evicted.
func (c *LRU) Put(key string, value int) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if el, ok := c.items[key]; ok {
		// Existing key: update value and mark as most recently used.
		el.Value.(*entry).value = value
		c.order.MoveToFront(el)
		return
	}

	// New key: evict the least recently used entry if at capacity.
	if c.order.Len() >= c.capacity {
		oldest := c.order.Back()
		if oldest != nil {
			c.order.Remove(oldest)
			delete(c.items, oldest.Value.(*entry).key)
		}
	}

	el := c.order.PushFront(&entry{key: key, value: value})
	c.items[key] = el
}

// Len returns the number of entries currently stored in the cache.
func (c *LRU) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()

	return c.order.Len()
}

